// ─── HELPERS ──────────────────────────────────────────────
function smoothScroll(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const root = document.scrollingElement || document.documentElement;
  const start = root.scrollTop;
  const target = el.getBoundingClientRect().top + start - 64;
  const dist = target - start;
  const dur = 420;
  let t0 = null;
  function step(ts) {
    if (!t0) t0 = ts;
    const p = Math.min((ts - t0) / dur, 1);
    root.scrollTop = start + dist * (1 - Math.pow(1 - p, 3));
    if (p < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

function useIsMobile() {
  const [mob, setMob] = useState(() => window.innerWidth <= 680);
  useEffect(() => {
    const fn = () => setMob(window.innerWidth <= 680);
    window.addEventListener("resize", fn);
    return () => window.removeEventListener("resize", fn);
  }, []);
  return mob;
}

// once-only scroll reveal
function Reveal({ children, style }) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined" ||
        window.matchMedia("(prefers-reduced-motion: reduce)").matches) { setInView(true); return; }
    // anything already at or above the viewport reveals immediately — the observer
    // only stages elements still below the fold
    if (el.getBoundingClientRect().top < window.innerHeight * 0.95) { setInView(true); return; }
    const ob = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) { setInView(true); ob.disconnect(); }
    }, { rootMargin: "0px 0px -10% 0px" });
    ob.observe(el);
    return () => ob.disconnect();
  }, []);
  return <div ref={ref} className={`rv${inView ? " rv-in" : ""}`} style={style}>{children}</div>;
}

