// ─── WAITLIST FORM (real Supabase; success unlocks board) ─
function WaitlistForm({ onSuccess }) {
  const [email, setEmail] = useState("");
  const [consent, setConsent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const submit = async () => {
    const e = email.trim().toLowerCase();
    if (!e) { setError("Email is required."); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) { setError("Enter a valid email."); return; }
    if (!consent) { setError("Please accept the privacy terms."); return; }
    if (!supabase) { setError("Backend not configured yet — see .env.example."); return; }

    setError(""); setLoading(true);
    const { error: dbError } = await supabase
      .from("waitlist")
      .insert({ email: e, name: null, plan: "board", source: "landing" });

    setLoading(false);
    if (dbError && dbError.code !== "23505") {
      setError("Something went wrong. Try again.");
      return;
    }
    // duplicate email (23505) still unlocks — they're already on the list
    trackLead("board");
    onSuccess();
  };

  return (
    <div style={{display:"flex",flexDirection:"column",gap:12}}>
      <div style={{display:"flex",gap:12,flexWrap:"wrap"}}>
        <input
          style={{
            flex:"1 1 220px",height:52,padding:"0 18px",borderRadius:12,
            background:whiteA(.06),border:`1px solid ${whiteA(.14)}`,color:C.paper,
            fontSize:14,fontFamily:"'Space Mono',monospace",outline:"none",minWidth:0,
          }}
          placeholder="you@store.eu" type="email" value={email} aria-label="Email"
          onChange={e=>setEmail(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submit()} autoComplete="email"
        />
        <Btn onClick={submit} disabled={loading} style={{flexShrink:0}}>
          {loading ? <><Spinner/> Joining…</> : "Get the full board"}
        </Btn>
      </div>
      <label style={{display:"flex",gap:8,alignItems:"flex-start",fontSize:12,color:whiteA(.6),cursor:"pointer",lineHeight:1.5}}>
        <input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}
          style={{marginTop:2,accentColor:C.mint,flexShrink:0,width:16,height:16}}/>
        <span>I agree that DropSynth stores my email to contact me about early access. I can request deletion anytime. <a href="/privacy.html" target="_blank" rel="noreferrer" style={{color:C.mint}}>Privacy policy</a></span>
      </label>
      {error && <div style={{fontSize:13,color:C.danger}}>{error}</div>}
      <span className="mono" style={{fontSize:11,letterSpacing:"0.1em",color:"rgba(0,230,160,.7)"}}>NO CARD. NO SPAM. FREE NOW · FOUNDER PRICE LATER.</span>
    </div>
  );
}

